$assisterCtrler.endAct();

var targetHeavy:Number = $assisterCtrler.getTarget().heavy;
var targetSpeed:Number = $assisterCtrler.getTarget().speed;

const LEVEL:Array = [0.8, 0.65, 0.5, 0.35, 0.2];
var index:int = int(targetHeavy>5 ? 5:targetHeavy) - 1;
var level:Number = LEVEL[index];

var finalSpeed:Number = targetSpeed * level;
var selfDirect:int = $assisterCtrler.getSelf().direct;

var targetSP:* = $assisterCtrler.owner_fighter_ctrler.getTargetSP();

$assisterCtrler.addCustomFunc(fuutonFunc);
function fuutonFunc():void {
	setTargetBulletSpeedLevel(level);

	var targetState:int = $assisterCtrler.owner_fighter_ctrler.getTargetState();
	if (targetState == 23) {
		return;
	}

	targetSP.x += finalSpeed * selfDirect;
}
function setTargetBulletSpeedLevel(speedLevel:Number = 0):void {
	var gameSprites:Vector.<*> = $assisterCtrler.getGameSprites();
	for each(var sp:* in gameSprites) {
		if (!$assisterCtrler.isBullet(sp)) {
			continue;
		}

		var isSelfTeam:Boolean = $assisterCtrler.getSelf().team.id == sp.team.id;
		if (isSelfTeam) {
			continue;
		}

		var direct:int = sp.direct==selfDirect ? -1:1;
		sp.speedLevel = speedLevel * direct;
	}
}

var ownerSpeed:Number = $assisterCtrler.getOwner().speed;
$assisterCtrler.getOwner().getBuffCtrl().speedUp(ownerSpeed * 0.25, 6);
